SELECT batting_team, MAX(inning_total) AS highest_team_score
FROM (
    SELECT batting_team, match_id, inning, SUM(runs_scored + extra_runs) AS inning_total
    FROM Deliveries
    WHERE match_id IN (
        SELECT match_id FROM Matches WHERE season = '2026'
    )
    GROUP BY batting_team, match_id, inning
)
GROUP BY batting_team;

